// Seeded presentation-only fixture. No authenticated route, fetch, timer or backend.
import React from 'react'
import { createRoot } from 'react-dom/client'
import { Hash, Layers3, Settings, Send, BarChart3, X } from 'lucide-react'
import '../../client/src/index.css'
import '../../client/src/App.css'
import { SharedObjectCard } from '../../client/src/features/spaces/SharedObjectCard'
import type { SpaceSharedObject } from '../../client/src/features/spaces/types'

const params = new URLSearchParams(location.search)
const scene = params.get('scene') ?? 'channel', theme = params.get('theme') ?? 'light'
if (theme === 'system') delete document.documentElement.dataset.theme
else document.documentElement.dataset.theme = theme
window.fetch = async () => { throw new Error('Network disabled in ownership fixture') }
const noop = () => {}
const poll: SpaceSharedObject = { id: 'poll', chat_id: 'general', message_id: 'm', object_type: 'poll', title: 'When should we review the project?', state: 'open', payload: { options: [{ id: 'a', text: 'Monday morning' }, { id: 'b', text: 'Tuesday afternoon' }], multiSelect: false }, created_by: 'sam', created_at: '2026-01-01T12:00:00Z', updated_at: '2026-01-01T12:00:00Z', terminal_at: null, channel_name: 'general', space_id: 'project', space_name: 'Project', message_seq: '1', my_response: { optionIds: ['a'] }, response_counts: { a: 3, b: 2 } }
function Card() { return <SharedObjectCard object={poll} userId="sam" canManage onRespond={noop} onStateChange={noop} /> }
function SettingsDialog() { return <div className="overlay space-dialog-overlay"><section className="account-dialog space-settings-dialog" role="dialog" aria-label="Space settings"><header className="space-settings-header"><div><p className="eyebrow">PROJECT</p><h2>Space settings</h2></div><button type="button" className="icon-button" aria-label="Close settings"><X size={15} /></button></header><div className="space-settings-layout"><nav className="space-settings-nav"><button type="button" className="is-active"><Settings size={14} /> Overview</button><button type="button">Members <small>4</small></button></nav><div className="space-settings-content"><header className="space-settings-section-heading"><h3>Overview</h3><p>Keep this Space easy to recognize.</p></header><form className="profile-form" onSubmit={e=>e.preventDefault()}><label><span>Space name</span><input defaultValue="Project" /></label><label><span>Description</span><textarea defaultValue="Shared plans and project updates." /></label><button type="submit" className="primary-button">Save changes</button></form></div></div></section></div> }
function Preview() { return <main className={`workspace has-active-${scene === 'updates' ? 'updates' : 'space'}`}>
  <nav className="primary-rail"><span className="brand-mark"><Layers3 size={22} /></span><button type="button" className="rail-item rail-item-active"><Layers3 size={18} /><span>Spaces</span></button><div className="rail-spacer" /><span className="avatar avatar-you">SR</span></nav>
  {scene === 'list' ? <section className="spaces-page"><header className="spaces-topbar"><div><p className="eyebrow">WORK TOGETHER</p><h1>Spaces</h1></div></header><div className="spaces-overview-content"><section className="spaces-intro"><span className="spaces-intro-icon"><Layers3 size={22} /></span><h2>A place for shared work</h2><p>Create a Space for your team.</p><form className="spaces-create-form" onSubmit={e=>e.preventDefault()}><label htmlFor="name">Space name</label><input id="name" defaultValue="Design team" /><button type="submit" className="primary-button">Create Space</button></form></section><section className="spaces-list"><h2>Your Spaces</h2><button type="button" className="space-list-card"><span className="space-card-mark"><Layers3 size={18} /></span><span><strong>Project</strong><small>4 channels · Owner</small></span></button></section></div></section>
  : scene === 'updates' ? <section className="updates-page"><header className="updates-header"><div><p className="eyebrow">YOUR WORKSPACE</p><h1>Updates</h1><p>Shared decisions and things that need you.</p></div><label className="updates-search"><input aria-label="Search updates" placeholder="Search updates" /></label></header><nav className="updates-filters"><button type="button" className="is-active">All</button><button type="button">Polls</button></nav><div className="updates-sections"><section className="updates-section"><header><span><BarChart3 size={18} /></span><div><h2>Needs you</h2><p>Questions awaiting a response</p></div><b>1</b></header><div className="updates-grid"><article className="updates-item"><div className="updates-item-context"><strong>Project</strong><span>#general</span></div><Card /><button type="button" className="updates-open-source">Open in channel</button></article></div></section></div></section>
  : <section className="spaces-page space-detail"><div className="space-work-area"><aside className="space-sidebar"><header className="space-server-header"><span className="space-server-icon"><Layers3 size={17} /></span><div><strong>Project</strong><small>Team work</small></div><button className="space-settings-button" type="button" aria-label="Settings"><Settings size={14} /></button></header><button className="space-all-spaces" type="button">All Spaces</button><div className="space-section-heading">TEXT CHANNELS</div><nav className="space-channel-list"><div className="space-channel-row is-active"><button className="space-channel" type="button"><Hash size={14} /><span>general</span></button></div></nav></aside><section className="space-channel-view"><header className="space-channel-header"><div><span><Hash size={16} />general</span><small>Shared plans and project updates</small></div><button type="button" className="space-topic-edit">Edit topic</button></header><div className="space-message-list"><article className="space-message"><header className="space-message-heading"><strong>Sam Rivera</strong><small>12:00</small></header><p>Here is the plan for our next review.</p><Card /></article></div><form className="space-message-composer" onSubmit={e=>e.preventDefault()}><textarea rows={2} placeholder="Message #general" aria-label="Message #general" /><div className="space-composer-toolbar"><button type="button" className="space-mention-toggle">@</button><button type="submit" className="space-send-button"><Send size={15} /><span>Send</span></button></div><small className="space-composer-note">Messages are visible to channel members.</small></form></section></div></section>}
  <nav className="mobile-bottom-nav"><button type="button">Chats</button><button type="button">Calls</button><button type="button">Updates</button><button type="button" aria-current="page">Spaces</button><button type="button">Account</button></nav>
  {scene === 'settings' && <SettingsDialog />}
</main> }
const root = import.meta.hot?.data.root ?? createRoot(document.getElementById('root')!)
if (import.meta.hot) import.meta.hot.data.root = root
root.render(<Preview />)
